s=''''''
b=base64.b64decode(s)
assert hashlib.sha256(b).hexdigest()=="e9d2aacd5fd0b56df49067d9a307b64eac29b4aeb7d10e16d407814ef4e57a56",'BLOCKED:PAYLOAD_SHA256_MISMATCH'
